fn fib(n: u32) -> u64 {
  let (mut a, mut b) = (0u64, 1u64);
  for _ in 0..n {
    let next = a + b;
    a = b;
    b = next;
  }
  a
}

fn find_user(id: u32) -> Result<String, String> {
  let users = vec!["alice", "bob", "carol"];
  users
    .get(id as usize)
    .map(|name| name.to_string())
    .ok_or_else(|| format!("user {id} not found"))
}

fn main() {
  match find_user(1) {
    Ok(name) => println!("found: {name}"),
    Err(e) => eprintln!("error: {e}"),
  }
}

fn sum_of_squares(numbers: &[i32]) -> i32 {
  numbers
    .iter()
    .filter(|n| **n > 0)
    .map(|n| n * n)
    .sum()
}

fn main() {
  let nums = [1, -2, 3, -4, 5];
  let total = sum_of_squares(&nums);
  println!("sum = {total}");
}
